@pytest.mark.parametrize("cryptogram,frequency_order,expected,is_visible", q6_testcases)
def test_q6(cryptogram, frequency_order, expected, is_visible):
    original = copy.deepcopy(cryptogram)
    result = decrypt_cryptogram(cryptogram, frequency_order)
    assert cryptogram == original
    assert type(result) is list
    assert len(result) == 2
    assert type(result[0]) is dict
    assert type(result[1]) is list
    assert len(result[1]) == len(cryptogram)
    if is_visible:
        assert result == expected
    else:
        assert hashcode(result) == expected

    # The worksheet also asks for a main() that reads and prints the result.
    # Check that behavior in the two visible test scenarios, without
    # increasing the total number of parametrized test cases.
    if is_visible:
        import builtins
        from io import StringIO
        from contextlib import redirect_stdout

        inputs = iter([str(len(cryptogram)), *cryptogram, frequency_order])
        original_input = builtins.input
        builtins.input = lambda prompt="": next(inputs)
        try:
            output = StringIO()
            with redirect_stdout(output):
                main()
            assert output.getvalue() == str(expected) + "\n"
        finally:
            builtins.input = original_input
